\begin{tikzpicture}[>=Stealth,every node/.style={draw,rounded corners,align=center}]
\node (A) at (0,0) {PDF输入};
\node (B) at (4,0) {结构化解析};
\node (C) at (8,0) {独立向量索引};
\node (D) at (12,0) {混合检索};
