\draw[->] (B) -- node[above,draw=none] {解析片段} (C);
\draw[->] (C) -- node[above,draw=none] {向量数据} (D);
\draw[->] (D) -- node[above,draw=none] {检索结果} (E);
\draw[->] (E) -- node[above,draw=none] {生成内容} (F);
\draw[->] (F) -- node[above,draw=none] {审查反馈} (G);
\end{tikzpicture}
